//! Kotlin/JVM models using the SDK's lossless numerics and transport JSON values.
use super::*;

pub(super) fn render(model: &Model) -> String {
    let mut out = format!(
        "// Generated by musubi bindgen from an admitted .to artifact. Do not edit.\nimport java.math.BigInteger\nimport org.hyperledger.iroha.sdk.numeric.KotodamaInt\nimport org.hyperledger.iroha.sdk.numeric.KotodamaDecimal\nimport org.hyperledger.iroha.sdk.numeric.KotodamaQuantity\nimport org.hyperledger.iroha.sdk.numeric.NumericV1Codec\n\nobject {} {{\n",
        model.namespace
    );
    out.push_str(include_str!("kotlin_runtime.txt"));
    writeln!(
        out,
        "const val codeHash: String = {}",
        quote(&model.code_hash)
    )
    .unwrap();
    for kind in ["View", "Kotoage", "Hajimari", "Kaizen"] {
        writeln!(out, "class {kind}Request<Value> internal constructor(val codeHash: String, val ordinal: Int, val entrypoint: String, val payload: Map<String, Any?>, val argumentSchemaJson: String, val returnSchemaJson: String, val decodeResult: (Any?) -> Value) {{ val kind: String = {} }}", quote(kind)).unwrap();
    }
    for (id, ty) in model.types.iter().enumerate() {
        if let Some(identity) = &ty.identity {
            writeln!(out, "/** Exact signed nominal identity: {identity} */").unwrap();
        }
        let name = &ty.name;
        match &ty.kind {
            Kind::Struct(fields) => product(
                &mut out,
                name,
                &fields
                    .iter()
                    .enumerate()
                    .map(|(i, (wire, child))| (field(i, wire), ty_expression(model, *child)))
                    .collect::<Vec<_>>(),
            ),
            Kind::Tuple(children) => product(
                &mut out,
                name,
                &children
                    .iter()
                    .enumerate()
                    .map(|(i, child)| (format!("item{i}"), ty_expression(model, *child)))
                    .collect::<Vec<_>>(),
            ),
            Kind::Enum(variants) => {
                writeln!(out, "enum class {name}(val wireName: String) {{").unwrap();
                for (i, variant) in variants.iter().enumerate() {
                    writeln!(
                        out,
                        " v{i}_{}({}){}",
                        identifier(variant),
                        quote(variant),
                        if i + 1 == variants.len() { ";" } else { "," }
                    )
                    .unwrap();
                }
                out.push_str("}\n");
            }
            _ => {}
        }
        writeln!(
            out,
            "private fun decode{id}(value: Any?): {} {{ {} }}",
            ty_expression(model, id),
            decode_body(model, &ty.kind, id)
        )
        .unwrap();
        writeln!(
            out,
            "private fun encode{id}(value: {}): Any? {{ {} }}",
            ty_expression(model, id),
            encode_body(&ty.kind)
        )
        .unwrap();
    }
    for (ordinal, entry) in model.entries.iter().enumerate() {
        let name = &entry.symbol;
        product(
            &mut out,
            &format!("{name}Args"),
            &entry
                .args
                .iter()
                .enumerate()
                .map(|(i, (wire, child))| (field(i, wire), ty_expression(model, *child)))
                .collect::<Vec<_>>(),
        );
        let pairs = entry
            .args
            .iter()
            .enumerate()
            .map(|(i, (wire, child))| {
                format!("{} to encode{child}(args.{})", quote(wire), field(i, wire))
            })
            .collect::<Vec<_>>()
            .join(", ");
        writeln!(
            out,
            "/** {} entrypoint {}; signed ordinal {ordinal}. */",
            entry.kind,
            quote(&entry.name)
        )
        .unwrap();
        writeln!(out, "fun {name}(args: {name}Args): {}Request<{}> = {}Request(codeHash, {ordinal}, {}, mapOf({pairs}), {}, {}, ::decode{})", entry.kind, ty_expression(model, entry.result), entry.kind, quote(&entry.name), quote(&entry.schema_json), quote(&entry.result_schema_json), entry.result).unwrap();
    }
    out.push_str("}\n");
    out
}

fn quote(source: &str) -> String {
    quoted(source).replace('$', "\\$")
}

fn product(out: &mut String, name: &str, fields: &[(String, String)]) {
    if fields.is_empty() {
        writeln!(out, "class {name}").unwrap();
    } else {
        writeln!(
            out,
            "data class {name}({})",
            fields
                .iter()
                .map(|(name, ty)| format!("val {name}: {ty}"))
                .collect::<Vec<_>>()
                .join(", ")
        )
        .unwrap();
    }
}

fn ty_expression(model: &Model, index: usize) -> String {
    match &model.types[index].kind {
        Kind::Struct(_) | Kind::Tuple(_) | Kind::Enum(_) => model.ty(index).into(),
        Kind::Option(child) => format!("OptionValue<{}>", ty_expression(model, *child)),
        Kind::Result(ok, err) => format!(
            "ResultValue<{}, {}>",
            ty_expression(model, *ok),
            ty_expression(model, *err)
        ),
        Kind::List(child, _) => format!("List<{}>", ty_expression(model, *child)),
        Kind::Leaf(leaf) => match leaf {
            EntrypointValueKindV1::Int => "KotodamaInt",
            EntrypointValueKindV1::Decimal => "KotodamaDecimal",
            EntrypointValueKindV1::Quantity => "KotodamaQuantity",
            EntrypointValueKindV1::Bool => "Boolean",
            EntrypointValueKindV1::Json => "Any?",
            EntrypointValueKindV1::DataSpaceId => "BigInteger",
            _ => "String",
        }
        .into(),
        Kind::Unit => "Unit".into(),
        Kind::Cursor => "String".into(),
    }
}

fn decode_body(model: &Model, kind: &Kind, id: usize) -> String {
    match kind {
        Kind::Struct(fields) => format!(
            "val fields = record(value, setOf({})); return {}({})",
            fields
                .iter()
                .map(|(wire, _)| quote(wire))
                .collect::<Vec<_>>()
                .join(", "),
            model.ty(id),
            fields
                .iter()
                .map(|(wire, child)| format!("decode{child}(fields[{}])", quote(wire)))
                .collect::<Vec<_>>()
                .join(", ")
        ),
        Kind::Tuple(children) => format!(
            "val items = array(value, {}, true); return {}({})",
            children.len(),
            model.ty(id),
            children
                .iter()
                .enumerate()
                .map(|(i, child)| format!("decode{child}(items[{i}])"))
                .collect::<Vec<_>>()
                .join(", ")
        ),
        Kind::Option(child) => format!(
            "val fields = record(value); require(fields.size == 1); if (fields.containsKey(\"some\")) return OptionValue.Some(decode{child}(fields[\"some\"])); require(fields[\"none\"] == true); return OptionValue.None"
        ),
        Kind::Result(ok, err) => format!(
            "val fields = record(value); require(fields.size == 1); if (fields.containsKey(\"ok\")) return ResultValue.Ok(decode{ok}(fields[\"ok\"])); if (fields.containsKey(\"err\")) return ResultValue.Err(decode{err}(fields[\"err\"])); fail()"
        ),
        Kind::List(child, capacity) => {
            format!("return array(value, {capacity}, false).map(::decode{child})")
        }
        Kind::Enum(_) => format!(
            "val text = string(value); return {}.values().firstOrNull {{ it.wireName == text }} ?: fail()",
            model.ty(id)
        ),
        Kind::Unit => "require(value == null); return Unit".into(),
        Kind::Cursor => "return bytes(value)".into(),
        Kind::Leaf(leaf) => format!(
            "return {}",
            match leaf {
                EntrypointValueKindV1::Int => "NumericV1Codec.decodeIntJsonValue(value)",
                EntrypointValueKindV1::Decimal => "NumericV1Codec.decodeDecimalJsonValue(value)",
                EntrypointValueKindV1::Quantity => "NumericV1Codec.decodeQuantityJsonValue(value)",
                EntrypointValueKindV1::Bool => "boolean(value)",
                EntrypointValueKindV1::Json => "json(value)",
                EntrypointValueKindV1::DataSpaceId => "dataspace(value)",
                EntrypointValueKindV1::Blob => "bytes(value)",
                _ => "string(value)",
            }
        ),
    }
}

fn encode_body(kind: &Kind) -> String {
    match kind {
        Kind::Struct(fields) => format!(
            "return mapOf<String, Any?>({})",
            fields
                .iter()
                .enumerate()
                .map(|(i, (name, child))| format!(
                    "{} to encode{child}(value.{})",
                    quote(name),
                    field(i, name)
                ))
                .collect::<Vec<_>>()
                .join(", ")
        ),
        Kind::Tuple(children) => format!(
            "return listOf({})",
            children
                .iter()
                .enumerate()
                .map(|(i, child)| format!("encode{child}(value.item{i})"))
                .collect::<Vec<_>>()
                .join(", ")
        ),
        Kind::Option(child) => format!(
            "return when (value) {{ is OptionValue.None -> mapOf(\"none\" to true); is OptionValue.Some -> mapOf(\"some\" to encode{child}(value.value)) }}"
        ),
        Kind::Result(ok, err) => format!(
            "return when (value) {{ is ResultValue.Ok -> mapOf(\"ok\" to encode{ok}(value.value)); is ResultValue.Err -> mapOf(\"err\" to encode{err}(value.value)) }}"
        ),
        Kind::List(child, capacity) => {
            format!("require(value.size <= {capacity}); return value.map(::encode{child})")
        }
        Kind::Enum(_) => "return value.wireName".into(),
        Kind::Unit => "return null".into(),
        Kind::Cursor => "return bytes(value)".into(),
        Kind::Leaf(leaf) => format!(
            "return {}",
            match leaf {
                EntrypointValueKindV1::Int => "NumericV1Codec.encodeIntJson(value)",
                EntrypointValueKindV1::Decimal => "NumericV1Codec.encodeDecimalJson(value)",
                EntrypointValueKindV1::Quantity => "NumericV1Codec.encodeQuantityJson(value)",
                EntrypointValueKindV1::Json => "json(value)",
                EntrypointValueKindV1::DataSpaceId => "dataspace(value)",
                EntrypointValueKindV1::Blob => "bytes(value)",
                EntrypointValueKindV1::Bool => "value",
                _ => "string(value)",
            }
        ),
    }
}
